from abc import ABC, abstractmethod

class Sink(ABC):
    @abstractmethod
    def push(self, x): ...

class ListSink(Sink):
    def push(self, x):
        return [x]

print(ListSink().push(7))

from abc import ABC, abstractmethod
class Job(ABC):
    @abstractmethod
    def run(self): ...
    def twice(self):
        return self.run() * 2

class Ping(Job):
    def run(self):
        return "p"

print(Ping().twice())

